import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Badge · Lazer DS Starter Kit
 * Figma: Components page, Badge set. Tone: Accent, Neutral, Inverse, Success, Warning, Error, Info.
 * Accent and Inverse are solid; Neutral and the feedback tones are tinted with a 1px edge.
 */
type Tone = "accent" | "neutral" | "inverse" | "success" | "warning" | "error" | "info"

const tones: Record<Tone, string> = {
  accent: "bg-[var(--component-badge-background)] text-[var(--component-badge-label)] border-transparent",
  inverse: "bg-[var(--component-badge-inverse-background)] text-[var(--component-badge-inverse-label)] border-transparent",
  neutral: "bg-[var(--component-badge-neutral-background)] text-[var(--component-badge-neutral-label)] border-[var(--component-badge-neutral-border)]",
  success: "bg-[var(--component-badge-success-background)] text-[var(--component-badge-success-label)] border-[var(--component-badge-success-border)]",
  warning: "bg-[var(--component-badge-warning-background)] text-[var(--component-badge-warning-label)] border-[var(--component-badge-warning-border)]",
  error: "bg-[var(--component-badge-error-background)] text-[var(--component-badge-error-label)] border-[var(--component-badge-error-border)]",
  info: "bg-[var(--component-badge-info-background)] text-[var(--component-badge-info-label)] border-[var(--component-badge-info-border)]",
}

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  tone?: Tone
  leadingIcon?: React.ReactNode
}

export function Badge({ tone = "accent", leadingIcon, className, children, ...props }: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-tone={tone}
      className={cn(
        "lz-label-caps inline-flex items-center gap-[var(--inline-xs)] whitespace-nowrap",
        "px-[var(--component-badge-padding-inline)] py-[var(--component-badge-padding-block)] rounded-[var(--component-badge-radius)]",
        "border-[length:var(--stroke-hairline)] border-solid",
        tones[tone],
        className
      )}
      {...props}
    >
      {leadingIcon ? <span className="inline-flex size-[var(--component-icon-size-sm)] [&>svg]:size-full">{leadingIcon}</span> : null}
      {children}
    </span>
  )
}
